    "title": "الدرس الأول (نص الاستماع): يوم جميل",
    "content": "قصة استماع تعزز السلوكيات الإيجابية والكلمات الطيبة بين الأطفال والأصدقاء في المدرس والبيت.\n\n• الفكرة الرئيسة: التعبير عن مشاعر الفرح، والتعاون مع الأصدقاء، والتحدث بلطف.\n• القيمة الأخلاقية: الاحترام والاعتذار وتقديم المساعدة.\n• مفردات القصة:\n - سعيد: مسرور\n - اعتذار: التراجع عن الخطأ بأسف\n - قصد: تعمُّد",
