    "content": "نص قراءة يعلم الطفل استخدام عبارات اللباقة والتهذيب في حياته اليومية.\n\n• المفردات الجديدة:\n - ابتسمت: ضحكت دون صوت\n - تزين القلوب: تجعل القلوب جميلة ومسرورة\n• عبارات جميله تعلمنا استخدامها:\n - من فضلك (عند الطلب)\n - شكراً (عند الامتنان)\n - آسف (عند الخطأ)\n - ملابسك جميلة (عند الإطراء والتودد)",
