    "content": "• المفرد: اسم يدل على شيء واحد فقط (مثل: قلم - حقيبة - ولد).\n• المثنى: اسم يدل على اثنين أو اثنتين بزيادة (ان) أو (ين) في نهايته (مثل: قلمان - حقيبتان - ولدان).\n\n• أمثلة للتطبيق:\n - كتاب -> كتابان\n - معلمة -> معلمان / معلمتان\n - شجرة -> شجرتان",
