    "title": "القواعد الإملائية: تحليل الكلمات إلى مقاطع صوتية",
    "content": "• قواعد التحليل الصوتي:\n 1. الحرف المتحرك (فتحة/ضمة/كسرة) يُشكل مقطعاً بمفرده.\n 2. الحرف الساكن يذهب مع ما قبله (المتحرك + الساكن = مقطع).\n 3. حرف المد يذهب مع الحرف الممدود قبله (المد + الممدود = مقطع).\n 4. الحرف المشدد يُفك إلى حرفين: الأول ساكن مع ما قبله، والثاني متحرك بمفرده.\n\n• أمثلة:\n - كَـ - تَـ - بَ (3 مقاطع)\n - مَدْ - رَ - سَ - ةٌ (4 مقاطع)\n - كِ - تَا - بٌ (3 مقاطع)",
