    "content": "• ظرف المكان: اسم يبين موقع وقوع الفعل (أسئلة: أين؟).\n - كلمات تدل عليه: (فوق - تحت - أمام - خلف - بين - داخل - خارج).\n - مثال: يقف المعلم أمام التلاميذ.\n\n• ظرف الزمان: اسم يبين وقت حدوث الفعل (أسئلة: متى؟).\n - كلمات تدل عليه: (صباحاً - مساءً - صيفاً - شتاءً - ليلاً - نهاراً).\n - مثال: تشرق الشمس صباحاً.",
