    "title": "القواعد الإملائية: اللام الشمسية واللام القمرية",
    "content": "• اللام القمرية (الْـ): تُكتب وتُلفظ، وتكون اللام ساكنة والحرف بعدها غير مشدد. حروفها (أ ب ج ح خ ع غ ف ق ك م هـ و ي).\n - مثال: الْقَمَر - الْكِتَاب - الْحَقِيبَة.\n\n• اللام الشمسية (الـ): تُكتب ولا تُلفظ، ويكون الحرف الواقع بعدها مشدداً. حروفها (ت ث د ذ ر ز س ش ص ض ط ظ ل ن).\n - مثال: الشَّمْس - الصَّبَاح - التِّلْمِيذ.",
