    "content": "شرح الدرس: نلاحظ الظاهرة ونطرح سؤالًا ونستخدم دليلًا بسيطًا، ثم نربط التعلم بحياة الطالب ودوره في مجتمعه.\n\nطريقة التعلم: نقرأ المثال أو نلاحظ الصورة، نحدد المهارة المطلوبة، ثم ننفذها خطوة خطوة.\n\nنشاط تفاعلي: المس العنصر التعليمي، انطق الكلمة أو العدد، ثم ارسم تطبيقًا جديدًا.\n\nتحقق من الفهم: اشرح كيف وصلت إلى إجابتك، وليس الإجابة فقط."
