    "content": "مراجعة منظمة: استرجع المفاهيم، نفذ تدريبًا قصيرًا، ثم اشرح فكرة رئيسية بصوتك.\n\nبطاقة التقييم: أتعرف المهارة، أطبقها، أتحقق من الحل، وأطلب المساعدة عند الحاجة.",
