    "id": "g2d-sources",
    "title": "خريطة مصادر الصف الثاني الرسمية",
    "content": "فهرس كتب الصف الثاني وأدلة المعلم:\nhttps://edu2-egypt.com/grade-2\n\nالمكتبة الإلكترونية لوزارة التربية والتعليم:\nhttps://ellibrary.moe.gov.eg/Books/Books-Primary",
    "subject": "اكتشف",
    "grade": "الثاني",
    "stage": "primary",
    "term": 1,
    "type": "lessons",
